#!/usr/bin/env node
/**
 * Turns the design system's tokens.json (the source of truth) into src/theme/tokens.generated.ts.
 *
 *   npm run tokens:sync    regenerate after tokens.json changes
 *   npm run tokens:check   fail if the generated file is out of date (run by `npm run build`)
 *
 * Token names keep their meaning, only the prefix is dropped and the rest camel-cased:
 *   color-text-muted → color.textMuted    space-4 → space[4]     radius-md → radius.md
 *   text-base → text.base                 tap-target → size.tapTarget
 *
 * Reads ../docs/design-system/tokens.json, or the path in HANDYSG_TOKENS.
 * If that file isn't there (e.g. a checkout without the docs folder), --check skips with a note.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const source = process.env.HANDYSG_TOKENS ?? resolve(root, "../docs/design-system/tokens.json");
const target = resolve(root, "src/theme/tokens.generated.ts");
const checkOnly = process.argv.includes("--check");

if (!existsSync(source)) {
  const msg = `tokens: ${source} not found.`;
  if (checkOnly) {
    console.warn(`${msg} Skipping the check.`);
    process.exit(0);
  }
  console.error(msg);
  process.exit(1);
}

const tokens = JSON.parse(readFileSync(source, "utf8"));

const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const px = (v) => {
  const m = /^(-?\d+(?:\.\d+)?)px$/.exec(String(v));
  if (!m) throw new Error(`tokens: expected a px value, got "${v}"`);
  return Number(m[1]);
};
const strip = (name, prefix) => {
  if (!name.startsWith(prefix)) throw new Error(`tokens: "${name}" should start with "${prefix}"`);
  return name.slice(prefix.length);
};

// Colours, per theme.
const color = { light: {}, dark: {} };
for (const t of tokens.color.tokens) {
  const key = camel(strip(t.name, "color-"));
  for (const theme of ["light", "dark"]) {
    if (!t.value[theme]) throw new Error(`tokens: ${t.name} has no ${theme} value`);
    color[theme][key] = t.value[theme];
  }
}

// Type scale. Weight is the default for that size; components may override it.
const text = {};
for (const group of tokens.type.groups) {
  for (const s of group.styles) {
    text[camel(strip(s.name, "text-"))] = {
      fontSize: px(s.fontSize),
      lineHeight: px(s.lineHeight),
      fontWeight: s.fontWeight,
    };
  }
}

const space = {};
for (const t of tokens.spacing.tokens) space[strip(t.name, "space-")] = px(t.value);

const radius = {};
for (const t of tokens.radius.tokens) radius[camel(strip(t.name, "radius-"))] = px(t.value);

const size = {};
for (const t of tokens.size.tokens) size[camel(t.name)] = px(t.value);

// Shadows: the value is the light theme; the dark colour is given in the usage text.
const shadow = { light: {}, dark: {} };
for (const t of tokens.shadow.tokens) {
  const key = camel(strip(t.name, "shadow-"));
  shadow.light[key] = t.value;
  const dark = /rgba\([^)]*\)/.exec(t.usage ?? "");
  shadow.dark[key] = dark ? t.value.replace(/rgba\([^)]*\)/, dark[0]) : t.value;
}

const json = (v) => JSON.stringify(v, null, 2);
const out = `// GENERATED by scripts/sync-tokens.mjs from docs/design-system/tokens.json. Do not edit by hand.
// Change tokens.json, then run \`npm run tokens:sync\`.

export const color = ${json(color)} as const;

export const text = ${json(text)} as const;

export const space = ${json(space)} as const;

export const radius = ${json(radius)} as const;

export const size = ${json(size)} as const;

export const shadow = ${json(shadow)} as const;
`;

if (checkOnly) {
  const current = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (current !== out) {
    console.error("tokens: src/theme/tokens.generated.ts is out of date. Run `npm run tokens:sync`.");
    process.exit(1);
  }
  console.log("tokens: up to date");
} else {
  writeFileSync(target, out);
  console.log(`tokens: wrote ${target}`);
}
